alter table public.transactions add constraint transactions_id_user_id_key unique(id,user_id);
create table public.saving_goal_dispositions(user_id uuid not null references auth.users(id) on delete cascade,operation_key text not null,goal_id uuid not null,kind text not null check(kind in('USE','CANCEL')),transaction_id uuid,created_at timestamptz not null default now(),primary key(user_id,operation_key),foreign key(goal_id,user_id) references public.saving_goals(id,user_id),foreign key(transaction_id,user_id) references public.transactions(id,user_id));
create index saving_goal_dispositions_goal_user_idx on public.saving_goal_dispositions(goal_id,user_id);
create index saving_goal_dispositions_transaction_user_idx on public.saving_goal_dispositions(transaction_id,user_id) where transaction_id is not null;
alter table public.saving_goal_dispositions enable row level security;
create policy saving_goal_dispositions_read on public.saving_goal_dispositions for select to authenticated using((select auth.uid())=user_id);
revoke all on public.saving_goal_dispositions from anon,authenticated; grant select on public.saving_goal_dispositions to authenticated;
create function public.use_saving_goal(p_goal_id uuid,p_amount bigint,p_category_id uuid,p_description text,p_note text,p_expected_version integer,p_operation_key text) returns public.transactions language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid(); g public.saving_goals; a public.accounts; c public.categories; l public.saving_virtual_locks; t public.transactions; existing uuid; next_saved bigint; begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if; select transaction_id into existing from public.saving_goal_dispositions where user_id=u and operation_key=p_operation_key; if found then select * into t from public.transactions where id=existing; return t; end if; select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update; if not found or g.lifecycle_status in('CANCELLED','ARCHIVED') then raise exception 'GOAL_NOT_AVAILABLE' using errcode='P0001'; end if; if g.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001'; end if; if p_amount<1 or p_amount>g.saved_amount then raise exception 'INVALID_GOAL_BALANCE' using errcode='P0001'; end if; select * into c from public.categories where id=p_category_id and user_id=u and type='EXPENSE' and deleted_at is null; if not found then raise exception 'CATEGORY_NOT_FOUND' using errcode='P0001'; end if; select * into a from public.accounts where id=case when g.funding_mode='VIRTUAL_LOCK' then g.source_account_id else g.savings_account_id end and user_id=u and deleted_at is null for update; if not found then raise exception 'ACCOUNT_NOT_FOUND' using errcode='P0001'; end if; if g.funding_mode='VIRTUAL_LOCK' then select * into l from public.saving_virtual_locks where goal_id=g.id for update; if l.id is null or l.locked_amount<p_amount then raise exception 'INSUFFICIENT_LOCK' using errcode='P0001'; end if; if l.locked_amount=p_amount then delete from public.saving_virtual_locks where id=l.id; else update public.saving_virtual_locks set locked_amount=locked_amount-p_amount where id=l.id; end if; end if; if a.balance<p_amount then raise exception 'INSUFFICIENT_BALANCE' using errcode='P0001'; end if; update public.accounts set balance=balance-p_amount where id=a.id; insert into public.transactions(user_id,account_id,category_id,category_name,type,amount,description,note,occurred_at,source,resulting_balance) values(u,a.id,c.id,c.name,'EXPENSE',-p_amount,coalesce(nullif(btrim(p_description),''),'Gunakan tabungan: '||g.name),nullif(btrim(p_note),''),now(),'MANUAL',a.balance-p_amount) returning * into t; next_saved:=g.saved_amount-p_amount; update public.saving_goals set saved_amount=next_saved,lifecycle_status=case when next_saved=0 then 'ARCHIVED' else 'ACTIVE' end where id=g.id; insert into public.saving_goal_dispositions(user_id,operation_key,goal_id,kind,transaction_id) values(u,p_operation_key,g.id,'USE',t.id); return t; end $$;
create function public.cancel_saving_goal(p_goal_id uuid,p_destination_account_id uuid,p_expected_version integer,p_operation_key text) returns public.saving_goals language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid(); g public.saving_goals; src public.accounts; dst public.accounts; l public.saving_virtual_locks; existing text; begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if; select kind into existing from public.saving_goal_dispositions where user_id=u and operation_key=p_operation_key; if found then select * into g from public.saving_goals where id=p_goal_id and user_id=u; return g; end if; select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update; if not found or g.lifecycle_status in('CANCELLED','ARCHIVED') then raise exception 'GOAL_NOT_AVAILABLE' using errcode='P0001'; end if; if g.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001'; end if; select * into dst from public.accounts where id=p_destination_account_id and user_id=u and deleted_at is null for update; if not found then raise exception 'ACCOUNT_NOT_FOUND' using errcode='P0001'; end if; if g.funding_mode='VIRTUAL_LOCK' then if dst.id<>g.source_account_id then raise exception 'INVALID_DESTINATION' using errcode='P0001'; end if; delete from public.saving_virtual_locks where goal_id=g.id; elsif g.saved_amount>0 then if dst.id=g.savings_account_id then raise exception 'INVALID_DESTINATION' using errcode='P0001'; end if; select * into src from public.accounts where id=g.savings_account_id and user_id=u and deleted_at is null for update; if src.balance<g.saved_amount then raise exception 'INSUFFICIENT_BALANCE' using errcode='P0001'; end if; update public.accounts set balance=balance-g.saved_amount where id=src.id; update public.accounts set balance=balance+g.saved_amount where id=dst.id; insert into public.account_transfers(user_id,source_account_id,destination_account_id,amount,note) values(u,src.id,dst.id,g.saved_amount,'Pembatalan goal: '||g.name); end if; update public.saving_goals set saved_amount=0,lifecycle_status='CANCELLED' where id=g.id returning * into g; insert into public.saving_goal_dispositions(user_id,operation_key,goal_id,kind) values(u,p_operation_key,g.id,'CANCEL'); return g; end $$;
revoke execute on function public.use_saving_goal(uuid,bigint,uuid,text,text,integer,text),public.cancel_saving_goal(uuid,uuid,integer,text) from public,anon;
grant execute on function public.use_saving_goal(uuid,bigint,uuid,text,text,integer,text),public.cancel_saving_goal(uuid,uuid,integer,text) to authenticated;
